def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    needy_pressure = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                needy_pressure += 1
            prev = opp.get('previous_trace', {}) or {}
            if prev.get('error'):
                continue
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, 18)

    avg_req = 0.0
    if len(alive) > 0:
        total_req = 0
        for opp in alive:
            total_req += opp.get('water_requirement', WATER_REQ)
        avg_req = total_req / float(len(alive))
    else:
        avg_req = WATER_REQ

    total_players_est = len(alive) + 1
    total_req_est = WATER_REQ + avg_req * len(alive)
    scarcity = total_req_est / max(float(supply), 1.0)

    if scarcity >= total_players_est:
        base = 58
    elif scarcity >= total_players_est * 0.8:
        base = 48
    elif scarcity >= total_players_est * 0.6:
        base = 38
    else:
        base = 26

    if hp <= 2:
        base += 26
    elif hp <= 4:
        base += 14

    if no_water_days >= 2:
        base += 22
    elif no_water_days >= 1:
        base += 10

    if supply >= 23:
        base -= 8
    elif supply <= 17:
        base += 8

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if highest_prev >= 60:
            if hp > 4 and no_water_days == 0:
                base = min(base, 28)
            else:
                base = max(base, highest_prev + 2)
        else:
            target = max(avg_prev + 2, highest_prev + 1)
            base = max(base, target)

    if needy_pressure >= max(1, len(alive) // 2):
        base += 6

    remaining_days = max(1, 10 - int(day) + 1)
    soft_cap = budget / float(remaining_days)
    if hp <= 2 or no_water_days >= 2:
        cap = max(soft_cap * 1.8, 35)
    elif hp <= 4 or no_water_days >= 1:
        cap = max(soft_cap * 1.35, 28)
    else:
        cap = max(soft_cap * 1.05, 22)

    bid = min(base, cap, budget)

    if day >= 8 and hp <= 4:
        bid = min(budget, max(bid, 52))

    if bid < 0:
        bid = 0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive = [o for o in opponents_status.values() if o['alive']]
    supply = day_context['supply']
    # Check if we have yesterday's trace to adapt
    highest_prev = 0
    for opp in alive:
        prev = opp.get('previous_trace')
        if prev and prev.get('bid') is not None:
            if prev['bid'] > highest_prev:
                highest_prev = prev['bid']
    # Base target
    if my_status['hp'] <= 3:
        target = DAILY_SALARY * 0.9
    else:
        n_alive = len(alive)
        if n_alive <= 2:
            target = DAILY_SALARY * 0.35
        else:
            target = DAILY_SALARY * 0.5
    # Adjust if opponent was aggressive yesterday
    if highest_prev > 0:
        # We want to beat the highest if we need water, else stay slightly below
        if my_status['hp'] <= 2 or my_status['no_water_days'] >= 2:
            target = max(target, highest_prev + 2.0)
        else:
            # Try to undercut if possible to save money
            target = min(target, highest_prev - 1.0)
            if target < 5:
                target = DAILY_SALARY * 0.3
    # Ensure within budget and positive
    target = max(1.0, min(my_status['budget'], target))
    return target
